insert into public.days (number, title, emoji, question, content) values (1, 'היי וביי לחרדה', '👋', 'ומה אם התקופה הזאת היא לא תקלה?', $json${"intro":["ומה אם מסתתרות בה מתנות שאת עדיין לא מסוגלת לראות?","היום אנחנו לא מנסות לפתור הכול.","אנחנו קודם כול מורידות קצת רעש, חוזרות לגוף ומתחילות ללמוד שפה חדשה:",{"b":"מה מרחיב אותי — ומה מכווץ אותי?"}],"task":{"title":"הסרטון שנפגוש שוב","body":["צלמי סרטון שלך עכשיו.",{"lines":["בלי להיות רוחנית.","בלי לנסות לראות את הטוב.","בלי לסדר את המחשבות לפני."]},"ספרי איפה את נמצאת עכשיו.",{"lines":["מה קשה?","מה מפחיד?","מה מבלבל?","מה נמאס לך?","מה את לא יודעת?"]},{"b":"שפכי הכול."},"תעלי את הסרטון למרחב האישי שלך כאן.","אנחנו נחזור אליו בהמשך הג׳רני :)",{"widget":"day1Video"}]},"game":{"title":"התרחבות / התכווצות","body":["היום הגוף שלך הופך למצפן.","לפני החלטות קטנות תשאלי:",{"b":"זה מרחיב אותי או מכווץ אותי?"},{"lines":["מה בא לי לאכול?","מה ללבוש?","עם מי בא לי להיפגש?","האם בא לי לצאת או להישאר בבית?","לענות עכשיו או אחר כך?"]},"אל תתחילי בהחלטות גורליות :)","אנחנו רק מתחילות להכיר את השפה של הגוף.",{"b":"היום אל תחפשי תשובות. תאספי מידע."}]}}$json$::jsonb)
on conflict (number) do update set title = excluded.title, emoji = excluded.emoji, question = excluded.question, content = excluded.content, updated_at = now();

insert into public.days (number, title, emoji, question, content) values (2, 'גם זה יעבור', '🌊', 'מי את כשאת מפסיקה למדוד את עצמך לפי מה שהשגת?', $json${"intro":["החיים זזים בגלים.","יש תקופות שבהן הכול טס, ויש תקופות שבהן הכול מרגיש תקוע, לא ברור או בתנועה פנימית.","אף אחת מהן לא מגדירה את הערך שלך."],"task":{"title":"במה אני גאה בי?","body":["תעלי לקהילה:",{"b":"10 דברים שאני גאה בעצמי עליהם שלא קשורים להישגים שלי."},"זה יכול להיות:",{"lines":["אני גאה במסע הרגשי שעברתי.","אני גאה בדרך שבה למדתי לשים גבולות.","אני גאה שלא דיברתי עם האקס שלי כבר שבוע 😂","אני גאה בדרך שבה אני אוהבת את האנשים שלי.","אני גאה בעצמי שאני עדיין כאן."]},"אחרי שהעלית את הרשימה שלך:",{"b":"תיכנסי לשיתופים של 3 נשים אחרות ותפרגני להן על משהו שאת רואה בהן."}]},"share":{"cta":"לשתף במה אני גאה ✨","label":"במה אני גאה","placeholder":"אני גאה בעצמי ש…"},"game":{"title":"נקודת מבט מעניינת","body":["בכל פעם שאת תופסת היום מחשבה כמו:",{"quotes":["אני מאחור.","בגילי כבר הייתי צריכה…","לכולן כבר יש ורק לי אין.","כנראה עשיתי טעות.","אני אמורה כבר לדעת מה אני רוצה."]},"אל תתווכחי איתה.","אל תנסי בכוח לחשוב חיובי.","פשוט תגידי:",{"b":"\"נקודת מבט מעניינת היא רק נקודת מבט מעניינת.\""},"אולי זו אמת.","ואולי זו פשוט נקודת מבט שחזרת עליה מספיק פעמים עד שהיא התחילה להרגיש כמו אמת.","היום אנחנו לא חייבות להאמין לכל מחשבה שעוברת לנו בראש."]}}$json$::jsonb)
on conflict (number) do update set title = excluded.title, emoji = excluded.emoji, question = excluded.question, content = excluded.content, updated_at = now();

insert into public.days (number, title, emoji, question, content) values (3, 'החזרת הריבונות', '👑', 'ומה אם את לא מחכה שהחיים ישתנו — אלא החיים מחכים שתזוזי?', $json${"intro":["היום אנחנו עוברות מ:",{"quotes":["למה זה קורה לי?"]},"ל:",{"b":"\"מה אני בוראת מכאן?\""},"לא כדי להאשים את עצמך.","בדיוק להפך.","אם יש לך חלק ביצירת המציאות שלך — יש לך גם כוח להשתתף ביצירת הדבר הבא."],"task":{"title":"5 דקות של היזכרות","body":["שימי אוזניות.","יש כאן קובץ קצר שהכנתי לך.","5 דקות שבהן את לא צריכה לפתור, להבין או לעשות.","רק להיזכר:",{"b":"אני לא מחכה לנס. אני משתתפת ביצירה שלו."},{"audio":{"title":"5 דקות של היזכרות","duration":"5:00"}}]},"game":{"title":"ומה כן בשליטתי?","body":["בכל פעם שאת תופסת את עצמך היום מתעסקת במשהו שאין לך שליטה עליו, תשאלי:",{"b":"אוקיי. ומה כן בשליטתי עכשיו?"},{"lines":["לא מחר.","לא כל החיים."]},{"b":"עכשיו."},"ואם עולה משהו קטן שאת יכולה לעשות — תעשי אותו."]}}$json$::jsonb)
on conflict (number) do update set title = excluded.title, emoji = excluded.emoji, question = excluded.question, content = excluded.content, updated_at = now();

insert into public.days (number, title, emoji, question, content) values (4, 'פעולות מקדמות', '→', 'איך את רוצה שהחיים שלך ירגישו — עוד לפני שאת יודעת איך הם ייראו?', $json${"intro":["אנחנו רגילות לנסות לפתור:",{"lines":["איזו עבודה?","איזה עסק?","איזה גבר?","איזו עיר?"]},"היום פחות מעניין אותנו ה\"איך\".","מעניין אותנו:",{"b":"איך אני רוצה להרגיש?"}],"task":{"title":"שתי רשימות","body":["פתחי שתי רשימות:",{"h":"אני לא מוכנה יותר להרגיש…"},"ואז:",{"h":"אני בוחרת להרגיש יותר…"},"לדוגמה:",{"lines":["חופש.","ביטחון.","תשוקה.","משחקיות.","שייכות.","עוצמה.","שקט."]},"עכשיו עצמי עיניים.","על כל רגש שבחרת תשאלי:",{"b":"\"גוף, תראה לי איך זה מרגיש.\""},"תני לעצמך כמה שניות להרגיש אותו.","ואז תשאלי:",{"b":"מה פעולה אחת קטנה שאני יכולה לעשות היום שתואמת את החיים האלה?"},"תעשי אותה.","לא צריך תוכנית חומש.","אנחנו רק מזיזות את החיים מילימטר לכיוון שאנחנו רוצות."]},"game":{"title":"אם הייתי כבר היא","body":["בכל פעם שאת עומדת לעשות משהו מתוך אוטומט, תשאלי:",{"b":"אם הייתי כבר האישה שמרגישה כמו שאני רוצה להרגיש — מה הייתי בוחרת עכשיו?"}]}}$json$::jsonb)
on conflict (number) do update set title = excluded.title, emoji = excluded.emoji, question = excluded.question, content = excluded.content, updated_at = now();

insert into public.days (number, title, emoji, question, content) values (5, 'להרגיש את השיפט', '✨', 'ומה אם המציאות כבר התחילה לזוז — ופשוט לא שמת לב?', $json${"intro":["היום אנחנו הופכות לבלשיות של שפע.","אנחנו לא מחכות רק לנס הענק.","אנחנו מתחילות לזהות את כל המקומות שבהם החיים כבר אומרים:",{"b":"היי מאמי, אני פה."}],"task":{"title":"תיק ההוכחות","body":["פתחי בפתקים בטלפון רשימה חדשה:",{"b":"\"הוכחות שהחיים איתי\""},"ומעכשיו — את מתעדת.",{"lines":["קיבלת קפה?","מישהו הציע לעזור לך?","הגיעה הזדמנות משום מקום?","נכנס כסף שלא ציפית לו?","פגשת בדיוק את האדם שהיית צריכה לפגוש?","קרה צירוף מקרים מצחיק?","משהו הסתדר בקלות?"]},{"b":"לפתקים."},"אבל זה לא נשאר רק בפתקים.","במהלך היום, תעלי את ההוכחות שלך גם לכאן.","כשאת משתפת משהו שקרה לך, מישהי אחרת במסע מקבלת הוכחה שזה אפשרי גם עבורה.","וכשאת נכנסת ורואה נשים אחרות משתפות במה שקורה להן, גם את מתחילה לראות שיש הרבה יותר אפשרויות ממה שחשבת.","לכן היום:",{"b":"שימי לב ← תתעדי ← תשתפי ← תקראי הוכחות של אחרות."}]},"share":{"cta":"להוסיף הוכחת שפע ✨","label":"הוכחת שפע","placeholder":"הנה זה. היום…","repeatable":true,"again":"להוסיף עוד הוכחה ✨"},"game":{"title":"\"הנה זה.\"","body":["בכל פעם שאת קולטת משהו טוב — קטן ככל שיהיה — תגידי:",{"b":"\"הנה זה.\""},"ואז תתעדי אותו."]}}$json$::jsonb)
on conflict (number) do update set title = excluded.title, emoji = excluded.emoji, question = excluded.question, content = excluded.content, updated_at = now();

insert into public.days (number, title, emoji, question, content) values (6, 'תודעת ראויה', '🍒', 'מי אמר שאת צריכה לחכות שהכול יסתדר כדי ליהנות?', $json${"intro":["יש חוזה מוזר שאנחנו לפעמים חותמות עליו:",{"lines":["קודם אפתור את הכסף.","אמצא זוגיות.","אבין מה אני עושה בחיים.","אצא מהתקופה הזאת."]},"**ואז** יהיה לי מותר ליהנות.","היום אנחנו משחקות עם אפשרות אחרת:",{"b":"מותר לי ליהנות גם באמצע."}],"task":{"title":"Pleasure Mission","body":["היום יש לך משימה אחת:",{"b":"לעשות משהו שהוא נטו בשביל הכיף."},{"lines":["לא מקדם אותך.","לא פרודוקטיבי.","לא \"טוב להתפתחות שלך\"."]},"משהו שהגרסה בת ה־8 שלך הייתה אומרת עליו:",{"b":"יאאאאאאאאאא."},"אחרי שעשית אותו — תעלי לקהילה תמונה או שיתוף קטן מהדייט שלך עם החיים."]},"share":{"cta":"לשתף רגע של כיף 🍒","label":"רגע של כיף","placeholder":"הדייט שלי עם החיים היום…"},"game":{"title":"10% יותר כיף","body":["בכל פעם שאת עושה משהו היום תשאלי:",{"b":"איך אפשר להפוך את זה ל־10% יותר כיף?"},{"lines":["מוזיקה במקלחת?","קפה בכוס היפה?","לרקוד בדרך לסופר?","להתלבש יפה סתם?"]},"אנחנו לא מחכות לחיים הטובים.","אנחנו מכניסות אותם פנימה עכשיו."]}}$json$::jsonb)
on conflict (number) do update set title = excluded.title, emoji = excluded.emoji, question = excluded.question, content = excluded.content, updated_at = now();

insert into public.days (number, title, emoji, question, content) values (7, 'תודעת זיבי', '💋', 'כמה מהחיים שלך בנויים על נקודות מבט שבכלל לא בחרת?', $json${"intro":[{"lines":["איך אישה אמורה להיראות.","כמה כסף \"נורמלי\" להרוויח.","באיזה גיל צריך להתחתן.","איך קריירה אמורה להיראות.","מה המשפחה שלך חושבת שאפשרי עבורך.","מה מערכת יחסים קודמת גרמה לך להאמין על עצמך.","מה נחשב \"אחראי\"."]},{"b":"היום אנחנו מתגרשות מכל חוזה שמצמצם אותנו."}],"task":{"title":"I CHOOSE TO BE FREE TODAY","body":["תתחילי במשפט:",{"h":"I choose to be free from…"},"ותוציאי הכול.","לדוגמה:",{"lines":["אני בוחרת להיות חופשייה מהצורך שכולם יבינו אותי.","אני בוחרת להיות חופשייה מהטיימליין שדמיינתי לעצמי.","אני בוחרת להיות חופשייה מהרעיון שכסף חייב להגיע בדרך מסוימת.","אני בוחרת להיות חופשייה מהסטנדרטים שלימדו אותי שאני צריכה לעמוד בהם."]},"ועכשיו:",{"h":"I choose to be free to…"},{"lines":["אני חופשייה לשנות את דעתי.","אני חופשייה להתחיל מחדש.","אני חופשייה להרוויח בדרך שנעימה לי.","אני חופשייה לבחור חיים שאנשים אחרים לא מבינים."]},{"b":"וכשסיימת, תעלי את הרשימה שלך לכאן."},"הרשימה לא נשארת רק אצלך.","יכול להיות שהחופש שאת נותנת לעצמך היום יהיה בדיוק ה־permission slip שמישהי אחרת במסע הייתה צריכה לקרוא."]},"share":{"cta":"לשתף את הצהרת החופש שלי 💋","label":"תודעת זיבי","placeholder":"I choose to be free from…"},"game":{"title":"נקודת מבט מעניינת","body":["בכל פעם שאת שומעת בראש:",{"quotes":["אבל צריך…","אי אפשר…","זה לא נורמלי…","מה יחשבו עליי?","ככה לא עושים דברים…"]},"תגידי:",{"b":"\"נקודת מבט מעניינת היא רק נקודת מבט מעניינת.\""},"ואז תשאלי:",{"b":"ומה אני בוחרת?"}]}}$json$::jsonb)
on conflict (number) do update set title = excluded.title, emoji = excluded.emoji, question = excluded.question, content = excluded.content, updated_at = now();

insert into public.days (number, title, emoji, question, content) values (8, 'למצוא את הייעוד שלך', '🧭', 'ומה אם הייעוד שלך הוא לא משהו שאת אמורה למצוא?', $json${"intro":["אולי ייעוד הוא לא מקצוע אחד שמסתתר איפשהו ואת צריכה לנחש אותו נכון.","אולי הוא נבנה בכל פעם שאת מסכימה להיות יותר את."],"task":{"title":"שאלות שפותחות מרחב","body":["קחי כמה דקות ותעני בלי לנסות להיות הגיונית.",{"widget":"purposeAnswers"},"אל תחפשי מקצוע.",{"b":"תחפשי חיות."}]},"game":{"title":"האם זה מרחיב אותי?","body":["לפני החלטות היום תשאלי:",{"b":"האם זה מרחיב אותי?"},"פחות:",{"lines":["האם זה הדבר המושלם?","האם אנשים יבינו?","האם אני יכולה להבטיח שזה יעבוד?"]},"ויותר:",{"b":"האם זה מרחיב אותי?"}]}}$json$::jsonb)
