insert into public.days (number, title, emoji, question, content) values (9, 'להיות המגדלור', '☀️', 'את קולטת שאת כבר לא בדיוק אותה אישה שנכנסה לכאן לפני 9 ימים?', $json${"intro":["זוכרת את הסרטון ההוא מיום 1?","הגיע הזמן לפתוח אותו."],"moment":{"opening":"יש משהו שהשארת לעצמך לפני 8 ימים…","reveal":"לפתוח אותו","before":["לפני שאת לוחצת:","לא לשפוט את האישה שהיית שם.",{"b":"להסתכל עליה כמו שהיית מסתכלת על מישהי שאת אוהבת."}],"watched":"ראיתי אותה","next":{"label":"ועכשיו, תורך","title":"לפגוש אותה","body":[{"b":"צלמי סרטון חדש."},"עני בו:",{"lines":["מה השתנה בי?","מה אני רואה היום שלא ראיתי אז?","על מה אני סומכת יותר?","מה למדתי על עצמי?","ומה הייתי רוצה להגיד לגרסה שלי מיום 1?"]},"בסוף, אם בא לך, תגידי לה:",{"b":"\"אני יודעת שאת עדיין לא יודעת מה מגיע מחר. אבל חכי שתראי מי את הולכת להיות.\""},{"widget":"day9Video"}]}},"extra":{"label":"טקס הסיום","title":"ודאות לפני העולם","body":["עכשיו אנחנו בונות טקס בוקר קטן שתוכלי לקחת איתך גם אחרי שה־JOURNEY מסתיים.","לא שגרת בוקר של שעה וחצי שתעשי שלושה ימים ואז תשנאי :)",{"b":"5–10 דקות."},"בחרי לעצמך כמה אלמנטים. הטקס צריך לענות על השאלה:",{"b":"איך אני רוצה לפגוש את עצמי לפני שאני פוגשת את העולם?"},{"widget":"ritual"}]},"game":{"label":"המשחק האחרון","title":"מי אני בוחרת להיות","body":["היום אל תשאלי:",{"quotes":["מה הולך לקרות?"]},"תשאלי:",{"b":"\"מי אני בוחרת להיות בתוך מה שיקרה?\""}]}}$json$::jsonb)
